#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<n);
        ops.push_back({x,y});
        vector<int> res;
        for(int i=n-y;i<n;i++) res.push_back(p[i]);
        for(int i=x;i<n-y;i++) res.push_back(p[i]);
        for(int i=0;i<x;i++) res.push_back(p[i]);
        p=res;
    };

    // Place elements from left to right
    for(int t=0; t<n-2; t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        int remaining = n - t; // elements from index t to n-1
        // Move element from pos to the last position (n-1) if not already there
        if(pos != n-1){
            // y = n - pos makes element at pos the first of suffix
            // x = 1 (minimum), need 1 + (n-pos) < n => pos > 1
            if(pos > 1){
                do_op(1, n-pos);
            } else if(pos == 1){
                // x >= 1, y = n-1, x+y < n => x < 1. Can't. 
                // Use two steps: first arbitrary op to move it
                if(n>3){ do_op(2,1); }
                else { do_op(1,1); }
                for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
                if(pos!=n-1 && pos>1) do_op(1, n-pos);
                else if(pos==n-1){/* ok */}
                else continue; // give up on this one for now
            }
            for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        }
        if(pos==t) continue;
        // Element at n-1, move to position t: x=t+1, y=1, need t+2<n
        if(pos==n-1 && t+2<=n-1){
            do_op(t+1, 1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
